Jump script:

```csharp
using UnityEngine;
public class Jump : MonoBehaviour {
    public float force = 5f;
    Rigidbody rb;
    void Start() { rb = GetComponent<Rigidbody>(); }
    void Update() {
        if (Input.GetKeyDown(KeyCode.Space)) rb.AddForce(Vector3.up * force, ForceMode.Impulse);
    }
}
